namespace decodium{void beginActiveSettingsProfile(QSettings&){}}
static void bridgeLog(const QString&){}
class DecodiumBridge{public:
 struct MamQsoSlot {enum class State{Done,Signoff,Active};QString callFull,call,grid,reportSent,reportReceived,lastTransmittedMessage;int audioFreqHz=0,progress=0,currentTx=0,partnerSnrDb=0,retryCount=0;bool logged=false;State state=State::Active;qint64 startedOnMs=0;};
 int m_mamMaxStreams=1,slotSignals=0,queueSignals=0,logCalls=0;bool m_mamCqSlots=false,m_ft2ElasticFox=false,m_mamPowerBudget=false,m_mamMultiStream=false,m_txEnabled=false,m_autoCqRepeat=false,m_multiAnswerMode=false,m_manualTxHold=false,legacy=false;QString m_mode="FT8";QVector<MamQsoSlot> m_mamSlots;QVector<int> m_mamLateReportRecoveries,m_mamF0sHz,m_callerQueue;QStringList m_mamMessages;
 void mamMaxStreamsChanged(){}void mamCqSlotsChanged(){}void digiPileupChanged(){}void mamActiveSlotsChanged(){++slotSignals;}void callerQueueChanged(){++queueSignals;}void setMamMultiStream(bool v){m_mamMultiStream=v;}bool isMamMultiStreamMode()const{return true;}bool usingLegacyBackendForTx()const{return legacy;}bool shouldUseBridgeAudioForLegacyDigitalTx()const{return true;}int mamSlotIndexForCall(const QString&call)const{for(int i=0;i<m_mamSlots.size();++i)if(m_mamSlots[i].call==call)return i;return -1;}void mamLogSlot(MamQsoSlot&s){s.logged=true;++logCalls;}void mamPruneSlots(){}void clearMamPendingTxPayload(const QString&){m_mamMessages.clear();m_mamF0sHz.clear();}
 void setMamMaxStreams(int);void setMamCqSlots(bool);void setDigiPileupElastic(bool);void setDigiPileupBudget(bool);void setDigiPileupEnabled(bool);QVariantList mamActiveSlots()const;QVariantList mamTxStreams()const;bool mamModeExperimental()const;void mamDropSlot(const QString&);void mamLogSlotNow(const QString&);void mamClearSlots();void mamClearQueue();bool mamMultiStreamSequencerActive()const;
};
#include "bridge_refactor_mam_controls.inc"
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir dir;QSettings::setPath(QSettings::IniFormat,QSettings::UserScope,dir.path());auto check=[](bool ok,const char*n){if(!ok){std::cerr<<n<<" failed\n";std::exit(1);}std::cout<<n<<'\n';};DecodiumBridge b;b.setMamMaxStreams(99);b.setMamCqSlots(true);b.setDigiPileupEnabled(true);QSettings s(QSettings::IniFormat,QSettings::UserScope,"Decodium","Decodium3");check(b.m_mamMaxStreams==10&&b.m_mamMultiStream&&b.m_ft2ElasticFox&&b.m_mamPowerBudget&&!b.m_txEnabled&&s.value("MamMaxStreams").toInt()==10,"settings-no-tx");DecodiumBridge::MamQsoSlot slot;slot.call="K1ABC";slot.callFull="K1ABC/P";slot.audioFreqHz=1500;slot.state=DecodiumBridge::MamQsoSlot::State::Signoff;b.m_mamSlots.append(slot);check(b.mamActiveSlots().size()==1&&b.mamActiveSlots()[0].toMap().value("state").toInt()==1,"slot-view");b.m_mamMessages={"CQ IU8LMC JN70","K1ABC IU8LMC -10",""};b.m_mamF0sHz={1000,1500,2000};auto streams=b.mamTxStreams();check(streams.size()==2&&streams[0].toMap().value("cq").toBool()&&!streams[1].toMap().value("cq").toBool(),"stream-view");b.m_mode="FT2";check(b.mamModeExperimental(),"experimental-mode");b.mamLogSlotNow("K1ABC");check(b.logCalls==1&&b.m_mamSlots[0].logged,"log-simulated");b.mamDropSlot("K1ABC");check(b.m_mamSlots.isEmpty(),"drop");b.mamClearSlots();check(b.m_mamMessages.isEmpty()&&b.m_mamF0sHz.isEmpty(),"clear-payload");b.m_callerQueue={1,2};b.m_mamLateReportRecoveries={3};b.mamClearQueue();check(b.m_callerQueue.isEmpty()&&b.m_mamLateReportRecoveries.isEmpty()&&b.queueSignals==1,"clear-queue");b.m_txEnabled=true;b.m_autoCqRepeat=true;check(b.mamMultiStreamSequencerActive(),"sequencer-active");b.m_manualTxHold=true;check(!b.mamMultiStreamSequencerActive(),"sequencer-hold");}
